import os, sys, tempfile, click
from click.testing import CliRunner

# 1 required flag
@click.command()
@click.option("--on/--off", is_flag=True, required=True)
def cli1(on): click.echo(on)
r = CliRunner().invoke(cli1, [])
print("1:", r.exit_code, r.output.strip().splitlines()[-1])
print("1b:", CliRunner().invoke(cli1, ["--on"]).output.strip())

# 3 flag_value envvar
@click.command()
@click.option("--upper", flag_value="upper", envvar="UPPER")
def cli3(upper): click.echo(repr(upper))
print("3:", CliRunner().invoke(cli3, [], env={"UPPER": "whatever"}).output.strip(),
      CliRunner().invoke(cli3, []).output.strip(),
      CliRunner().invoke(cli3, ["--upper"]).output.strip())

# 4 decorator reuse
class MyArg(click.Argument): pass
class MyOpt(click.Option): pass
my_arg = click.argument("name", cls=MyArg)
my_opt = click.option("--x", cls=MyOpt)
@click.command()
@my_arg
@my_opt
def f1(name, x): pass
@click.command()
@my_arg
@my_opt
def f2(name, x): pass
print("4:", [type(p).__name__ for p in f1.params], [type(p).__name__ for p in f2.params])

# 5 resolve_path
d = tempfile.mkdtemp()
open(os.path.join(d, "real.txt"), "w").close()
os.symlink("real.txt", os.path.join(d, "link"))
os.chdir("/")
@click.command()
@click.option("--p", type=click.Path(resolve_path=True))
def cli5(p): click.echo(p)
print("5:", CliRunner().invoke(cli5, ["--p", os.path.join(d, "link")]).output.strip(), "expected", os.path.join(d, "real.txt"))

# 6 show_default with default_map
@click.command()
@click.option("--name/--no-name", is_flag=True, show_default=True)
def foo(name): click.echo(name)
print("6:", CliRunner().invoke(foo, ["--help"], default_map={"name": True}).output.split("[")[1].split("]")[0])
PYEOF
